47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 *
63	 * A test now guards this — "caps a policy covering a sword and 3 runes at
64	 * 3500 G". Deriving these values from the base premiums, or routing both
65	 * through a shared summing helper, makes the block rule reach the insurance
66	 * sum and yields a cap of 2120 instead of 3500.
67	 */
68	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	const DEDUCTIBLE = 100;
77	const CAP_MULTIPLE = 2;
78	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
79	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
80	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
81	const CURSE_SURCHARGE_PERCENT = 50;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
84	const LOYALTY_THRESHOLD_YEARS = 2;
85	const LOYALTY_DISCOUNT_PERCENT = 20;
86	const FOLLOWUP_DISCOUNT_PERCENT = 15;
87	const PROCESSING_FEE = 5;
88	
89	const percentOf = (amount: number, percent: number): number =>
90	  (amount * percent) / 100;
91	
92	/**
93	 * The MHPCO insures only what is on its price list. Looking a type up through
94	 * here rather than indexing a table directly means an unknown type cannot slip
95	 * through as `undefined` and surface later as a NaN premium.
96	 */
97	const priceOf = (
98	  priceList: Record<string, number>,
99	  itemType: string,
100	): number => {
101	  const price = priceList[itemType];
102	  if (price === undefined) {
103	    throw new Error(`unknown item type: ${itemType}`);
104	  }
105	  return price;
106	};
107	
108	/**
109	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
110	 * the opposite direction, so this deliberately names the premium case only
111	 * rather than a general "in the MHPCO's favour" rounding.
112	 */
113	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
114	
115	const BLOCK_SIZE = 3;
116	const BLOCK_BASE_PREMIUM = 60;
117	
118	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
119	const countAlikeItems = (items: Item[]): Map<string, number> =>
120	  items.reduce(
121	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
122	    new Map<string, number>(),
123	  );
124	
125	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
126	
127	const basePremiumForAlikeItems = (type: string, count: number): number =>
128	  formsBuildingBlock(count)
129	    ? BLOCK_BASE_PREMIUM
130	    : count * priceOf(BASE_PREMIUM_BY_ITEM_TYPE, type);
131	
132	const policyBasePremium = (items: Item[]): number =>
133	  [...countAlikeItems(items)].reduce(
134	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
135	    0,
136	  );
137	
138	const itemBasePremium = (item: Item): number =>
139	  priceOf(BASE_PREMIUM_BY_ITEM_TYPE, item.type);
140	
141	/**
142	 * An absent `enchantment` reads as 0 — a plain rune is not enchanted at all.
143	 * The threshold is a parameter because the MHPCO sets two different bars: 5
144	 * for the premium surcharge, 8 for the payout clause.
145	 */
146	const enchantmentAtLeast = (
147	  item: Item | undefined,
148	  threshold: number,
149	): boolean => (item?.enchantment ?? 0) >= threshold;
150	
151	const isHighlyEnchanted = (item: Item): boolean =>
152	  enchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
153	
154	/** Item-specific surcharges stack additively. */
155	const itemSurchargePercent = (item: Item): number =>
156	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
157	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
158	
159	/**
160	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
161	 * premium — unlike policy-wide modifiers, which apply to the policy base.
162	 */
163	const totalItemSurcharges = (items: Item[]): number =>
164	  items.reduce(
165	    (total, item) =>
166	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
167	    0,
168	  );
169	
170	const isLongStanding = (customer: Customer): boolean =>
171	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
172	
173	/**
174	 * The net of all policy-wide percentages. Policy-wide modifiers are
175	 * percentages of the POLICY base premium — unlike item-specific modifiers,
176	 * which apply to the affected item's own base. The net is negative when the
177	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
178	 */
179	const netPolicyAdjustmentPercent = (
180	  customer: Customer,
181	  precedingSteps: number,
182	): number =>
183	  FIRST_INSURANCE_SURCHARGE_PERCENT -
184	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
185	  // The follow-up discount is owed on every quote after the customer's FIRST
186	  // QUOTE, but what we have here is a count of preceding STEPS. The two
187	  // coincide only because every step exercised so far is a quote; once claim
188	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
189	  // as a second follow-up. No test forces the distinction yet.
190	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
191	
192	const policyAdjustment = (
193	  policyBase: number,
194	  customer: Customer,
195	  precedingSteps: number,
196	): number =>
197	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
198	
199	const quotePremium = (
200	  items: Item[],
201	  customer: Customer,
202	  precedingSteps: number,
203	): number => {
204	  const basePremium = policyBasePremium(items);
205	  return roundPremiumUp(
206	    basePremium +
207	      totalItemSurcharges(items) +
208	      policyAdjustment(basePremium, customer, precedingSteps) +
209	      PROCESSING_FEE,
210	  );
211	};
212	
213	const roundPayoutDown = (payout: number): number => Math.floor(payout);
214	
215	const insuranceSum = (items: Item[]): number =>
216	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
217	
218	const damagedItem = (damage: Damage, policyItems: Item[]): Item | undefined =>
219	  policyItems.find((item) => item.type === damage.itemType);
220	
221	/**
222	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
223	 * Highly enchanted items are reimbursed at half the damage amount.
224	 *
225	 * NOT A BUG: the spec's "dragon material is fully reimbursed" clause is
226	 * deliberately absent, because no example can observe it. Full reimbursement is
227	 * already what happens when no clause fires, so below enchantment 8 a dragon
228	 * item is indistinguishable from a steel one; at enchantment >= 8 the spec says
229	 * the 50 % rule wins, so dragon is indistinguishable again. The clause has no
230	 * input that would change an output — adding it would be unfalsifiable by the
231	 * suite. Both dragon tests below pass against this code for exactly the reasons
232	 * their comments state. If a future rule ever makes material observable (say, a
233	 * dragon-only exemption from the deductible, or a clause the 50 % rule does not
234	 * override), add it then, driven by that example.
235	 *
236	 * The enchantment is read from the FIRST policy item of the damaged type; see
237	 * `damagedItem`. With two alike items that differ in enchantment the wrong one
238	 * would be consulted — no example distinguishes them yet.
239	 */
240	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
241	  enchantmentAtLeast(
242	    damagedItem(damage, policyItems),
243	    HIGH_ENCHANTMENT_PAYOUT_THRESHOLD,
244	  )
245	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
246	    : damage.amount;
247	
248	/**
249	 * One damaged item's contribution to the payout. The deductible comes off ONCE
250	 * PER DAMAGED ITEM, not once per incident — expressing it at the level of a
251	 * single damage is what makes that per-item scope structural rather than a
252	 * remark about where a subtraction happens to sit.
253	 */
254	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
255	  reimbursementFor(damage, policyItems) - DEDUCTIBLE;
256	
257	/**
258	 * The whole incident's payout, before rounding — the per-item payouts summed.
259	 * NOT named for reimbursement: `reimbursementFor` is the amount BEFORE the
260	 * deductible, and reusing that word here would invite a reader to subtract it
261	 * a second time.
262	 */
263	const payoutBeforeRounding = (incident: Incident, policyItems: Item[]): number =>
264	  incident.damages.reduce(
265	    (total, damage) => total + payoutForDamage(damage, policyItems),
266	    0,
267	  );
268	
269	/** A claim's `policy` field is the index of the quote step that wrote it. */
270	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
271	  scenario.steps[policy].items ?? [];
272	
273	/** The MHPCO caps a policy at twice its insurance sum. */
274	const capFor = (policyItems: Item[]): number =>
275	  CAP_MULTIPLE * insuranceSum(policyItems);
276	
277	/**
278	 * A policy's cap is consumed cumulatively: each payout draws down what remains,
279	 * and a claim can never pay out more than is left. The clamp is applied AFTER
280	 * rounding, so a fractional payout cannot round its way past the remaining cap.
281	 *
282	 * Takes the policy's items and its remaining cap rather than looking either up,
283	 * which keeps the arithmetic of a single claim free of the ledger's bookkeeping.
284	 * `capLedger.settle` resolves both and is the only caller.
285	 */
286	const settleClaim = (
287	  incident: Incident,
288	  policyItems: Item[],
289	  remainingBefore: number,
290	): ClaimResult => {
291	  const desired = roundPayoutDown(payoutBeforeRounding(incident, policyItems));
292	  const payout = Math.min(desired, remainingBefore);
293	  return { payout, remainingCap: remainingBefore - payout };
294	};
295	
296	/**
297	 * Tracks what each policy has left of its cap as claims land against it, and
298	 * settles claims against it. A policy is seeded from its items the first time
299	 * it is claimed against, which is why this needs the scenario: the cap is a
300	 * property of the covered items, and those live in the quote step the claim
301	 * points at.
302	 *
303	 * Settling lives here rather than in the caller because the drawdown is the
304	 * whole reason the ledger exists: reading what remains, paying out of it, and
305	 * writing back what is left are one indivisible step, and a caller that could
306	 * read without writing back could silently let a policy pay twice over.
307	 */
308	const capLedger = (scenario: Scenario) => {
309	  const remainingByPolicy = new Map<number, number>();
310	
311	  return {
312	    settle: (policy: number, incident: Incident): ClaimResult => {
313	      const policyItems = itemsCoveredBy(policy, scenario);
314	      const remainingBefore =
315	        remainingByPolicy.get(policy) ?? capFor(policyItems);
316	      const result = settleClaim(incident, policyItems, remainingBefore);
317	      remainingByPolicy.set(policy, result.remainingCap);
318	      return result;
319	    },
320	  };
321	};
322	
323	/**
324	 * Steps are processed in order because claims draw down a policy's remaining
325	 * cap, so each result depends on the claims before it.
326	 */
327	export const runScenario = (scenario: Scenario): ScenarioResult => {
328	  const caps = capLedger(scenario);
329	
330	  const results = scenario.steps.map((step, precedingSteps) => {
331	    if (step.op !== "claim") {
332	      return {
333	        premium: quotePremium(
334	          step.items ?? [],
335	          scenario.customer,
336	          precedingSteps,
337	        ),
338	      };
339	    }
340	
341	    // Non-null: only claim steps reach here, and every claim carries an
342	    // incident. See the Step doc comment.
343	    return caps.settle(step.policy ?? 0, step.incident!);
344	  });
345	
346	  return { results };
347	};
